function save(){localStorage.setItem('wwi_deep_students',JSON.stringify(students));render();}
function addStudent(){let name=document.getElementById('sname').value;let grade=document.getElementById('sgrade').value;let phone=document.getElementById('sphone').value;if(!name){alert('Please enter Student Name — For Liberia Africa World — With Love — 💗');return;}let id='WWI-'+String(students.length+1).padStart(3,'0');students.push({id:id,name:name,grade:grade,phone:phone,attendance:{},feesPaid:0,feesTotal:100,scores:{Math:0,English:0,Science:0,History:0}});save();alert('🏫 WWI School App DEEP — STUDENT ADDED — '+name+' — ID: '+id+' — Grade: '+grade+' — For 1 School In Duala — 100 Students — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Real — Then Depth Will Spread To All — ✨💯✅🛜🏭 — Today — All Today — Yes 🙌 — For Mrs. Victoria K. Bangalu Sheriff — With Love — ❤️');document.getElementById('sname').value='';}
function markAttendance(id,status){let today=new Date().toISOString().split('T')[0];let s=students.find(x=>x.id===id);s.attendance[today]=status;save();alert('🏫 WWI School App DEEP — ATTENDANCE — '+s.name+' — '+today+' — '+status+' — Real Attendance — Real — For 1 School In Duala — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Then Depth Will Spread To All — ✨💯✅🛜🏭');}
