function updateScore(id,subject){let val=parseInt(prompt('Enter Score for '+subject+' — 0 to 100 — For '+students.find(x=>x.id===id).name,'85'));if(isNaN(val))return;let s=students.find(x=>x.id===id);s.scores[subject]=val;save();alert('📊 WWI School App DEEP — SCORE UPDATED — '+s.name+' — '+subject+': '+val+' — Real Report Cards — Real — For 1 School In Duala — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Then Depth Will Spread To All — ✨💯✅🛜🏭');}
function showReport(id){let s=students.find(x=>x.id===id);let total=Object.values(s.scores).reduce((a,b)=>a+b,0);let avg=(total/4).toFixed(1);let attCount=Object.values(s.attendance).filter(v=>v==='Present').length;let attTotal=Object.keys(s.attendance).length;let attPct=attTotal?((attCount/attTotal)*100).toFixed(0):0;let gradeLetter=avg>=90?'A':avg>=80?'B':avg>=70?'C':avg>=60?'D':'F';document.getElementById('reportArea').innerHTML='<div class=report><h2 style=text-align:center>🏫 WWI School App DEEP — Real Report Card — Real — For 1 School In Duala — 100 Students — For Liberia Africa World 🌍 — For Future — With Love — 💗</h2><p><b>Student:</b> '+s.name+' — <b>ID:</b> '+s.id+' — <b>Grade:</b> '+s.grade+' — <b>Phone:</b> '+s.phone+'</p><table><tr><th>Subject</th><th>Score</th><th>Grade</th></tr><tr><td>Math</td><td>'+s.scores.Math+'</td><td>'+(s.scores.Math>=90?'A':s.scores.Math>=80?'B':s.scores.Math>=70?'C':'D')+'</td></tr><tr><td>English</td><td>'+s.scores.English+'</td><td>'+(s.scores.English>=90?'A':s.scores.English>=80?'B':s.scores.English>=70?'C':'D')+'</td></tr><tr><td>Science</td><td>'+s.scores.Science+'</td><td>'+(s.scores.Science>=90?'A':s.scores.Science>=80?'B':s.scores.Science>=70?'C':'D')+'</td></tr><tr><td>History</td><td>'+s.scores.History+'</td><td>'+(s.scores.History>=90?'A':s.scores.History>=80?'B':s.scores.History>=70?'C':'D')+'</td></tr></table><p><b>Average:</b> '+avg+' — <b>Grade:</b> '+gradeLetter+' — <b>Attendance:</b> '+attCount+'/'+attTotal+' Days Present — '+attPct+'% — Real Attendance — Real — For Liberia Africa World 🌍</p><p><b>Fees:</b> Paid: \$'+s.feesPaid+' USD = L\$'+(s.feesPaid*CBL).toLocaleString()+' L\$ — Total: \$'+s.feesTotal+' USD = L\$'+(s.feesTotal*CBL).toLocaleString()+' L\$ — Balance: \$'+(s.feesTotal-s.feesPaid)+' USD = L\$'+((s.feesTotal-s.feesPaid)*CBL).toLocaleString()+' L\$ — At CBL L\$'+CBL.toFixed(2)+' Real Rate — No Fake Rates — For Economy — For GOV-NET — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Real Fees — Real</p><p style=text-align:center><b>Blockchain Hack-Proof — Report Card Verified — WWI School App DEEP — For 1 School In Duala — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Then Depth Will Spread To All — ✨💯✅🛜🏭 — For Mrs. Victoria K. Bangalu Sheriff — With Love — ❤️ — Today — All Today — Yes 🙌 — Completed 💯✅</b></p><button onclick=document.getElementById(`reportArea`).innerHTML=``>Close Report Card</button> <button onclick=window.print()>🖨️ Print Report Card — Real — For Liberia Africa World 🌍</button></div>';window.scrollTo(0,document.getElementById('reportArea').offsetTop);}
function render(){let totalStudents=students.length;let totalPresentToday=0;let today=new Date().toISOString().split('T')[0];let totalFeesPaid=students.reduce((a,s)=>a+s.feesPaid,0);let totalFeesExpected=students.reduce((a,s)=>a+s.feesTotal,0);students.forEach(s=>{if(s.attendance[today]==='Present')totalPresentToday++;});document.getElementById('stats').innerHTML='🏫 WWI School App DEEP — Real — For 1 School In Duala — 100 Students — Today: '+today+'<br>Total Students: '+totalStudents+' — Present Today: '+totalPresentToday+' — Absent Today: '+(totalStudents-totalPresentToday)+'<br>Fees Collected: \$'+totalFeesPaid.toLocaleString()+' USD = L\$'+(totalFeesPaid*CBL).toLocaleString()+' L\$ — Expected: \$'+totalFeesExpected.toLocaleString()+' USD = L\$'+(totalFeesExpected*CBL).toLocaleString()+' L\$ — Balance: \$'+(totalFeesExpected-totalFeesPaid).toLocaleString()+' USD = L\$'+((totalFeesExpected-totalFeesPaid)*CBL).toLocaleString()+' L\$ — At CBL L\$169.50 Real Rate — No Fake Rates — For Economy — For GOV-NET — For Liberia Africa World 🌍 — For Future — With Love — 💗 — Real Attendance — Real Report Cards — Real Fees — Real — Then Depth Will Spread To All — ✨💯✅🛜🏭';let html='';students.forEach(s=>{let todayStatus=s.attendance[today]||'Not Marked';let attCount=Object.values(s.attendance).filter(v=>v==='Present').length;let attTotal=Object.keys(s.attendance).length;html+='<tr><td>'+s.id+'</td><td>'+s.name+'</td><td>'+s.grade+'</td><td>'+todayStatus+'</td><td>'+attCount+'/'+attTotal+'</td><td>\$'+s.feesPaid+' / \$'+s.feesTotal+' — L\$'+(s.feesPaid*CBL).toLocaleString()+' / L\$'+(s.feesTotal*CBL).toLocaleString()+'</td><td><span class='+(s.feesPaid>=s.feesTotal?'paid':'unpaid')+'>'+(s.feesPaid>=s.feesTotal?'PAID ✅':'UNPAID ❌')+'</span></td><td><button onclick=markAttendance(`'+s.id+'`,`Present`)>✅ Present</button><button onclick=markAttendance(`'+s.id+'`,`Absent`)>❌ Absent</button><button onclick=payFees(`'+s.id+'`)>💰 Pay Fees</button><button onclick=showReport(`'+s.id+'`)>📊 Report Card</button><button onclick=updateScore(`'+s.id+'`,`Math`)>Math</button><button onclick=updateScore(`'+s.id+'`,`English`)>English</button><button onclick=updateScore(`'+s.id+'`,`Science`)>Science</button><button onclick=updateScore(`'+s.id+'`,`History`)>History</button></td></tr>';});document.getElementById('studentTable').innerHTML=html;}
window.onload=render;
</script>
